"""Same archived fit QP, test stricter absolute-only stopping; no physical gate changes."""
import argparse,datetime,json
from pathlib import Path
import numpy as np,scipy.sparse as sp,osqp
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--directory',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();P=sp.load_npz(a.directory/'linear_failed_P.npz');A=sp.load_npz(a.directory/'linear_failed_A.npz');z=np.load(a.directory/'linear_failed_vectors.npz');cs=z['column_scale'];rs=z['row_scale'];C=sp.diags(cs);D=sp.diags(rs);B=(D@A@C).tocsc();l=z['lower'];u=z['upper'];original=z['step'];ax=B@z['solver_x'];rows=[]
for relative in [1e-8,0.]:
 solver=osqp.OSQP();solver.setup(P=sp.triu(C@P@C,format='csc'),q=cs*z['gradient'],A=B,l=rs*l,u=rs*u,verbose=False,eps_abs=1e-8,eps_rel=relative,max_iter=100000,polishing=True);result=solver.solve();step=cs*result.x;violation=np.maximum.reduce([np.zeros(len(l)),l-A@step,A@step-u]);record=dict(eps_abs=1e-8,eps_rel=relative,status=result.info.status,iterations=result.info.iter,primal_residual=result.info.prim_res,dual_residual=result.info.dual_res,original_unit_violation=float(violation.max()),worst_row=int(violation.argmax()),original_unit_gate_pass=bool(result.info.status_val==1 and violation.max()<=1e-7),step_difference_from_archived=float(abs(step-original).max()));rows.append(record);np.savez_compressed(a.output.parent/('same_qp_abs_only_step.npz' if relative==0 else 'same_qp_original_replay_step.npz'),step=step);print(record,flush=True)
out=dict(time_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Same first-fit archived P/A/q/bounds/scales/budget; relative stopping only. No nonlinear or physics acceptance.',archived_worst_row=int(np.maximum(l-A@original,A@original-u).argmax()),scaled_constraint_value_abs_max=float(abs(ax).max()),column_scale_range=[float(cs.min()),float(cs.max())],row_scale_range=[float(rs.min()),float(rs.max())],rows=rows);a.output.write_text(json.dumps(out,indent=2)+'\n')
